  "adm1.acc.err.tooLong": ["Kontonummer zu lang (max. 20 Zeichen).", "Numéro de compte trop long (max. 20 caractères).", "Numero di conto troppo lungo (max. 20 caratteri).", "Account number too long (max. 20 characters)."],
  "adm1.acc.err.format": ["Kontonummern bestehen aus Ziffern, Buchstaben, Punkt oder Bindestrich.", "Les numéros de compte se composent de chiffres, lettres, points ou traits d’union.", "I numeri di conto sono composti da cifre, lettere, punto o trattino.", "Account numbers consist of digits, letters, dots or hyphens."],
  "adm1.acc.field.bankAccount.label": ["Bank / Post", "Banque / Poste", "Banca / Posta", "Bank / Post"],
  "adm1.acc.field.bankAccount.hint": ["Aktivkonto für Zahlungseingänge per Bank, Post und online (KMU 1020 Bankguthaben).", "Compte d’actif pour les paiements reçus par banque, poste et en ligne (PME 1020 Avoirs bancaires).", "Conto attivo per i pagamenti in entrata tramite banca, posta e online (PMI 1020 Averi bancari).", "Asset account for incoming payments by bank, post and online (SME 1020 Bank balances)."],
  "adm1.acc.field.cashAccount.label": ["Kasse", "Caisse", "Cassa", "Cash"],
  "adm1.acc.field.cashAccount.hint": ["Aktivkonto für Bargeld (KMU 1000 Kasse): Barverkäufe der Schützenstube und Reservationen «Bar / vor Ort». Wird die Kasse auf die Bank einbezahlt, bucht ihr das in der Buchhaltung (Bank / Kasse).", "Compte d’actif pour l’argent liquide (PME 1000 Caisse) : ventes au comptant de la buvette et réservations «Comptant / sur place». Lorsque la caisse est versée à la banque, vous le comptabilisez (banque / caisse).", "Conto attivo per i contanti (PMI 1000 Cassa): vendite in contanti della buvette e prenotazioni «Contanti / sul posto». Quando la cassa viene versata in banca, lo registrate in contabilità (banca / cassa).", "Asset account for cash (SME 1000 Cash): clubhouse bar cash sales and bookings “Cash / on site”. When the cash is paid into the bank, record it in your accounts (bank / cash)."],
  "adm1.acc.field.receivableAccount.label": ["Debitoren", "Débiteurs", "Debitori", "Receivables"],
  "adm1.acc.field.receivableAccount.hint": ["Forderungen aus Rechnungen (KMU 1100). Rechnung ausgestellt: Soll Debitoren, bezahlt: Haben Debitoren.", "Créances issues des factures (PME 1100). Facture émise : débit débiteurs ; payée : crédit débiteurs.", "Crediti da fatture (PMI 1100). Fattura emessa: dare debitori; pagata: avere debitori.", "Receivables from invoices (SME 1100). Invoice issued: debit receivables; paid: credit receivables."],
  "adm1.acc.field.feeAccount.label": ["Mitgliederbeiträge", "Cotisations des membres", "Quote sociali", "Membership fees"],
  "adm1.acc.field.feeAccount.hint": ["Ertrag aus Jahresbeiträgen und Vereinsrechnungen (KMU 3000).", "Produits des cotisations annuelles et des factures de la société (PME 3000).", "Ricavi da quote annuali e fatture della società (PMI 3000).", "Revenue from annual fees and club invoices (SME 3000)."],
  "adm1.acc.field.workFeeAccount.label": ["Ersatzabgabe Arbeitsstunden", "Taxe de remplacement heures de travail", "Tassa sostitutiva ore di lavoro", "Replacement fee for work hours"],
  "adm1.acc.field.workFeeAccount.hint": ["Ertrag aus Rechnungen, deren Bezeichnung mit «Ersatzabgabe» beginnt (Vorschlag 3010).", "Produits des factures dont la désignation commence par «Ersatzabgabe» (proposition 3010).", "Ricavi da fatture la cui designazione inizia con «Ersatzabgabe» (proposta 3010).", "Revenue from invoices whose title starts with “Ersatzabgabe” (suggestion 3010)."],
  "adm1.acc.field.bookingAccount.label": ["Standmiete / Reservationen", "Location du stand / réservations", "Affitto stand / prenotazioni", "Range hire / bookings"],
  "adm1.acc.field.bookingAccount.hint": ["Ertrag aus Reservationsrechnungen sowie Online- und Barzahlungen von Reservationen (Vorschlag 3400).", "Produits des factures de réservation ainsi que des paiements en ligne et au comptant des réservations (proposition 3400).", "Ricavi da fatture di prenotazione nonché da pagamenti online e in contanti delle prenotazioni (proposta 3400).", "Revenue from booking invoices and online and cash payments for bookings (suggestion 3400)."],
  "adm1.acc.field.kioskAccount.label": ["Ertrag Schützenstube", "Produits de la buvette", "Ricavi buvette", "Clubhouse bar revenue"],
  "adm1.acc.field.kioskAccount.hint": ["Ertrag aus Rechnungen der Schützenstube (Konsumationen auf Rechnung) und aus Barverkäufen an der Theke (Vorschlag 3600).", "Produits des factures de la buvette (consommations sur facture) et des ventes au comptant au comptoir (proposition 3600).", "Ricavi da fatture della buvette (consumazioni su fattura) e da vendite in contanti al banco (proposta 3600).", "Revenue from clubhouse bar invoices (items on account) and cash sales at the counter (suggestion 3600)."],
  "adm1.acc.field.ammoAccount.label": ["Munitionsverkauf", "Vente de munitions", "Vendita di munizioni", "Ammunition sales"],
  "adm1.acc.field.ammoAccount.hint": ["Ertrag aus Munitionsrechnungen (Vorschlag 3200). Munition wird nur per Rechnung verkauft, nie online.", "Produits des factures de munitions (proposition 3200). Les munitions sont vendues uniquement sur facture, jamais en ligne.", "Ricavi da fatture di munizioni (proposta 3200). Le munizioni vengono vendute solo su fattura, mai online.", "Revenue from ammunition invoices (suggestion 3200). Ammunition is only sold by invoice, never online."],
  "adm1.acc.field.feesExpenseAccount.label": ["Zahlungsgebühren", "Frais de paiement", "Commissioni di pagamento", "Payment fees"],
  "adm1.acc.field.feesExpenseAccount.hint": ["Aufwand für Gebühren der Zahlungsanbieter (KMU 6940). Die Anbieter melden die Gebühren nicht pro Zahlung an Standchef; bucht sie anhand der Abrechnung von Payrexx, Stripe, Worldline oder SumUp manuell (Zahlungsgebühren / Bank).", "Charges pour les frais des prestataires de paiement (PME 6940). Les prestataires ne communiquent pas les frais par paiement à Standchef ; comptabilisez-les manuellement sur la base du décompte de Payrexx, Stripe, Worldline ou SumUp (frais de paiement / banque).", "Costi per le commissioni dei fornitori di pagamento (PMI 6940). I fornitori non comunicano le commissioni per singolo pagamento a Standchef; registratele manualmente in base al conteggio di Payrexx, Stripe, Worldline o SumUp (commissioni di pagamento / banca).", "Expense for payment provider fees (SME 6940). Providers do not report fees per payment to Standchef; book them manually from the Payrexx, Stripe, Worldline or SumUp statement (payment fees / bank)."],
  "adm1.acc.howTitle": ["So wird gebucht", "Comment les écritures sont passées", "Come vengono registrate", "How entries are booked"],
  "adm1.acc.how.issue": ["Rechnung ausgestellt: Soll Debitoren ({receivable}) / Haben Ertrag (Beiträge {fee}, Ersatzabgabe {workFee}, Reservationen {booking}, Munition {ammo}).", "Facture émise : débit débiteurs ({receivable}) / crédit produits (cotisations {fee}, taxe de remplacement {workFee}, réservations {booking}, munitions {ammo}).", "Fattura emessa: dare debitori ({receivable}) / avere ricavi (quote {fee}, tassa sostitutiva {workFee}, prenotazioni {booking}, munizioni {ammo}).", "Invoice issued: debit receivables ({receivable}) / credit revenue (fees {fee}, replacement fee {workFee}, bookings {booking}, ammunition {ammo})."],
  "adm1.acc.how.paid": ["Rechnung bezahlt (auch online): Soll Bank ({bank}) / Haben Debitoren am Zahlungsdatum.", "Facture payée (aussi en ligne) : débit banque ({bank}) / crédit débiteurs à la date de paiement.", "Fattura pagata (anche online): dare banca ({bank}) / avere debitori alla data di pagamento.", "Invoice paid (also online): debit bank ({bank}) / credit receivables on the payment date."],
